-- Generated by Anno Session Regions ${toolkit_version}. Do not edit by hand.
-- Module: ${module_name}
-- Restores ${count} items outside ${session_name} (${session_guid}).
-- Re-registers the game's own unlock triggers, so each player keeps the progress
-- they earned. Items without a trigger are unlocked directly.

local ITEMS = {
${items}
}

local ALWAYS_UNLOCKED = {
${always}
}

for i = 1, #ALWAYS_UNLOCKED do
    pcall(ts.Unlock.SetUnlockNet, ALWAYS_UNLOCKED[i])
end

local MARKER = "${marker}"

local handle = io.open(MARKER, "r")
if handle then
    handle:close()
    return
end

local triggers = {}
local direct = {}

for i = 1, #ITEMS do
    local ok, trigger = pcall(ts.ToolOneDataHelper.GetUnlockTriggerForAsset, ITEMS[i])
    trigger = ok and tonumber(trigger) or nil
    if trigger and trigger ~= 0 then
        triggers[trigger] = true
    else
        direct[#direct + 1] = ITEMS[i]
    end
end

for trigger in pairs(triggers) do
    pcall(ts.Conditions.RegisterTriggerForCurrentParticipant, trigger)
end

for i = 1, #direct do
    pcall(ts.Unlock.SetUnlockNet, direct[i])
end

local out = io.open(MARKER, "w")
if out then
    out:write("1\n")
    out:close()
end
